const fs = require('fs');
const path = require('path');
const axios = require('axios'); // axios is recommended for FormData in Node.js
const { v4: uuidv4 } = require('uuid');

async function uploadFile(filePath) {
  const API_KEY = 'YOUR_API_KEY';
  const fileId = uuidv4();
  const stats = fs.statSync(filePath);
  const fileSize = stats.size;
  const recommendedChunkSize = 20 * 1024 * 1024; // 20 MB recommended chunk size
  // ensure at least 2 chunks for small files to avoid single-chunk upload issues
  const chunkSize = Math.min(recommendedChunkSize, Math.max(Math.floor(fileSize / 2), 1024 * 1024));
  const totalChunks = Math.ceil(fileSize / chunkSize);
  const fileName = path.basename(filePath);

  for (let i = 0; i < totalChunks; i++) {
    const start = i * chunkSize;
    const end = Math.min(start + chunkSize, fileSize);
    const chunk = fs.createReadStream(filePath, { start, end: end - 1 });
    const chunkNumber = i + 1;

    const formData = new FormData();
    formData.append('id', fileId);
    formData.append('chunk_number', chunkNumber.toString());
    formData.append('chunk_total', totalChunks.toString());
    formData.append('filename', fileName);
    formData.append('localTime', '2026-04-25T15:30:00+03:00');
    formData.append('template_name', 'default');
    formData.append('title', 'Meeting Upload');
    formData.append('file', chunk, fileName);

    try {
      const response = await axios.post('https://backend.mymeet.ai/api/video', formData, {
        headers: { 'Content-Type': 'multipart/form-data', 'X-API-KEY': API_KEY }
      });
      console.log(`Chunk ${chunkNumber}/${totalChunks} uploaded.`);
    } catch (error) {
      console.error(`Error uploading chunk ${chunkNumber}:`, error.response?.data || error.message);
      break;
    }
  }
}

import okhttp3.*;
import java.io.*;
import java.util.UUID;

public class ChunkUploader {
    public static void main(String[] args) throws IOException {
        OkHttpClient client = new OkHttpClient();
        File file = new File("PATH_TO_FILE");
        String apiKey = "YOUR_API_KEY";
        String fileId = UUID.randomUUID().toString();

        long fileSize = file.length();
        long recommendedChunkSize = 20 * 1024 * 1024; // 20 MB recommended chunk size
        // ensure at least 2 chunks for small files to avoid single-chunk upload issues
        long chunkSize = Math.min(recommendedChunkSize, Math.max(fileSize / 2, 1024 * 1024));
        int totalChunks = (int) Math.ceil((double) fileSize / chunkSize);

        try (RandomAccessFile raf = new RandomAccessFile(file, "r")) {
            for (int i = 0; i < totalChunks; i++) {
                int chunkNumber = i + 1;
                byte[] buffer = new byte[(int) Math.min(chunkSize, fileSize - (long) i * chunkSize)];
                raf.readFully(buffer);

                RequestBody fileBody = RequestBody.create(buffer, MediaType.parse("application/octet-stream"));

                MultipartBody requestBody = new MultipartBody.Builder()
                        .setType(MultipartBody.FORM)
                        .addFormDataPart("id", fileId)
                        .addFormDataPart("chunk_number", String.valueOf(chunkNumber))
                        .addFormDataPart("chunk_total", String.valueOf(totalChunks))
                        .addFormDataPart("filename", file.getName())
                        .addFormDataPart("localTime", "2026-04-25T15:30:00+03:00")
                        .addFormDataPart("template_name", "default")
                        .addFormDataPart("title", "Meeting Upload")
                        .addFormDataPart("file", file.getName(), fileBody)
                        .build();

                Request request = new Request.Builder()
                        .url("https://backend.mymeet.ai/api/video")
                        .post(requestBody)
                        .addHeader("X-API-KEY", apiKey)
                        .build();

                try (Response response = client.newCall(request).execute()) {
                    if (response.isSuccessful()) {
                        System.out.println("Chunk " + chunkNumber + "/" + totalChunks + " uploaded.");
                    } else {
                        System.err.println("Upload failed: " + response.body().string());
                        break;
                    }
                }
            }
        }
    }
}

