import okhttp3.*;
import okio.BufferedSink;
import okio.Okio;
import java.io.File;
import java.io.IOException;

public class Main {
  public static void main(String[] args) throws IOException {
    OkHttpClient client = new OkHttpClient();

    HttpUrl url = HttpUrl.parse("https://backend.mymeet.ai/api/storage/download").newBuilder()
        .addQueryParameter("meeting_id", "YOUR_MEETING_ID")
        .addQueryParameter("format", "pdf")
        .build();

    Request request = new Request.Builder().url(url).addHeader("X-API-KEY", "YOUR_API_KEY").get().build();

    try (Response response = client.newCall(request).execute()) {
      if (response.isSuccessful()) {
        File file = new File("meeting_report.pdf");
        try (BufferedSink sink = Okio.buffer(Okio.sink(file))) {
          sink.writeAll(response.body().source());
        }
        System.out.println("File saved to: " + file.getAbsolutePath());
      }
    }
  }
}

